INSERT INTO am_blueprint.nodes(snapshot_code,node_key,parent_key,kind,title,domain_code,original_module_id,baseline_status,verification,metadata)
SELECT 'AM-BLUEPRINT-2026-10-25-V1',n.node_key,n.parent_key,n.kind,n.title,n.domain_code,
 CASE WHEN n.kind='module' THEN (SELECT id FROM public.am_platform_modules m WHERE m.code=split_part(n.node_key,':',2) LIMIT 1) ELSE NULL::uuid END,
 n.baseline_status,n.verification,coalesce(n.metadata,'{}'::jsonb)
FROM incoming n
ON CONFLICT (snapshot_code,node_key) DO NOTHING;

